  min-height: 100vh;
  padding: 2rem 1rem;
}

main {
  max-width: 36rem;
  margin: 0 auto;
}

h1 {
  font-size: 1.75rem;
  margin: 0 0 1.5rem;
  letter-spacing: -0.01em;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -40px;
  background: var(--surface);
  color: var(--text);
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  border: 2px solid var(--focus);
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 0.5rem; }

.form-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 8px 24px rgba(0,0,0,0.35);
}

.form-field { margin-bottom: 1.25rem; }

fieldset {
  border: 0;
  padding: 0;
  margin: 0;
}

legend {
  padding: 0;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.25rem;
}

.required-marker {
  color: var(--danger);
  margin-left: 0.15rem;
}

.help-text {
  margin: 0 0 0.85rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.options {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.option {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 0.9rem;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  transition: border-color 120ms ease, background-color 120ms ease;
}

.option:hover {
  border-color: var(--border-strong);
}

.option:has(input:checked) {
  border-color: var(--accent);
  background: #1c2638;
}

/* Custom-looking but native radio. Keep native semantics & focus. */
.option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  border: 2px solid var(--border-strong);
  border-radius: 50%;
  background: transparent;
  margin: 0;
  display: inline-grid;
  place-content: center;
  cursor: pointer;
  flex: 0 0 auto;
}

.option input[type="radio"]::before {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: var(--accent-strong);
  transform: scale(0);
  transition: transform 120ms ease;
}

.option input[type="radio"]:checked {
  border-color: var(--accent);
}
.option input[type="radio"]:checked::before {
  transform: scale(1);
}

.option input[type="radio"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.option label {
  cursor: pointer;
  flex: 1;
  color: var(--text);
}

.submit-btn {
  margin-top: 0.5rem;
  background: var(--accent);
  color: #0b1020;
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  padding: 0.65rem 1.1rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 120ms ease, transform 120ms ease;
}

.submit-btn:hover { background: var(--accent-strong); }
.submit-btn:active { transform: translateY(1px); }
.submit-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  margin: 1rem 0 0;
  min-height: 1.5em;
  color: var(--text-muted);
}
.status.success { color: #8ee0a1; }
.status.error { color: var(--danger); }

/* Forced colors / Windows high-contrast support */
@media (forced-colors: active) {
  .option { border-color: CanvasText; }
  .option input[type="radio"] { border-color: CanvasText; }
  .option input[type="radio"]:checked::before { background: Highlight; }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }
  .skip-link { border-color: Highlight; }
}
